 jumiaEditor={kind:'jumiaOrders',record,storeId:store.id,lines:structuredClone(record?.lines||[]).map(l=>{const p=state.products.find(p=>p.id===l.productId);return {...l,returnedToStock:l.returnedToStock||(l.status==='La livraison a échoué'&&!l.lost),sku:l.sku||'',purchasePrice:l.dispatched?l.purchasePrice:p?.delegatePurchasePrice??p?.lastPurchasePrice??p?.purchasePrice??l.purchasePrice};})};const costs=record?.costs||{supplierTransport:0,hubTransport:20,returnTransport:0,ticketQty:1,ticketUnitPrice:1,saltKg:1,saltUnitPrice:2,cartonQty:1,cartonUnitPrice:2,other:0};
