function captureJumiaLines(){const form=$('#jumia-order-form');return jumiaEditor.lines.map((l,i)=>{const get=k=>form.elements['jl'+i+'_'+k];const updated={...l};for(const k of ['name','sku','jumiaSku','status'])updated[k]=get(k).value;for(const k of ['qty','supplierId',...jumiaMoneyFields])updated[k]=Number(get(k).value);updated.commissionActual=get('commissionActual').value===''?null:Number(get('commissionActual').value);for(const k of ['fromStock','returnedToStock','lost'])updated[k]=get(k).checked;updated.fromStock=!!updated.productId;return updated;});}
