function renderJumiaImportsContent(){
 const reports=(state.jumiaReports||[]).filter(r=>r.active!==false&&(!jumiaImportStore||String(r.storeId)===jumiaImportStore)),selected=reports.find(r=>String(r.id)===jumiaImportReport),rows=(selected?[selected]:reports).flatMap(r=>r.transactions),a=analyzeJumiaTransactions(rows),comparison=compareJumiaReports(selected?[selected]:reports,state.jumiaOrders);
 return `${canManageJumia()?catalogImportMarkup()+orderImportMarkup()+orderCorrectionMarkup():''}<div class="panel"><h3>Importer un relevé de transactions Jumia</h3><p>L’ID à la fin du Statement Number doit correspondre à l’ID de la boutique (Boutiques → Modifier). Un fichier contenant un autre ID est refusé.</p><form id="jumia-import-form"><label>Boutique<select name="storeId" required><option value="">Choisir une boutique</option>${state.jumiaStores.filter(s=>s.active!==false).map(s=>`<option value="${s.id}" ${String(s.id)===jumiaImportStore?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Export transactions CSV (2 Mo maximum)<input type="file" name="csvFile" accept=".csv,text/csv" required></label><label>Gasoil restant du dernier plein (%)<input name="fuelRemainingPercent" type="number" min="0" max="100" step="any" value="0" required></label><button>Importer et analyser</button><p id="jumia-import-error" role="alert"></p></form><div id="jumia-report-update-preview"></div></div><div class="panel"><h3>Analyse des imports</h3><label>Boutique<select id="jumia-import-store"><option value="">Toutes les boutiques</option>${state.jumiaStores.map(s=>`<option value="${s.id}" ${String(s.id)===jumiaImportStore?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Relevé<select id="jumia-import-report"><option value="">Tous les imports actifs</option>${reports.map(r=>`<option value="${r.id}" ${r.id===selected?.id?'selected':''}>${esc(r.fileName)} — ${esc(r.storeName)} — ${esc(r.createdAt.slice(0,10))}</option>`).join('')}</select></label></div><div class="cards">${[['Ventes créditées',a.sales],['Commission Jumia',a.commission],['Shipping prélevé',a.shipping],['Net du relevé',a.net],['Net marqué PAID',a.paid],['Net restant (hors PAID)',a.open]].map(([label,n])=>`<div class="card">${label}<strong>${money(n/100)}</strong></div>`).join('')}</div><p class="dashboard-charge-note">${a.count} transactions · ${a.orders.length} commandes · ${a.excluded} transactions hors APPROVED exclues. Montants Amount en MAD. Net = somme des crédits et débits approuvés. PAID est le statut du relevé Jumia. Le virement entre dans la trésorerie uniquement après confirmation du montant réellement reçu ci-dessous. Le net ne déduit pas vos coûts d’achat, transport et emballage.</p>${jumiaPayoutMarkup(reports)}${jumiaOrderPaymentsMarkup(selected?[selected]:reports)}${renderJumiaComparison(comparison)}${[['Par commande',a.orders]].map(([title,data])=>`<div class="panel" style="overflow:auto"><h3>${title}</h3>${table([title==='Par commande'?'Commande':'SKU vendeur','Ventes créditées','Frais nets','Net'],data.map(g=>[esc(g.key),money(g.sales/100),money(g.fees/100),money(g.net/100)]))}</div>`).join('')}<div class="panel"><h3>Par type de transaction</h3>${table(['Type','Montant net'],a.types.map(t=>[esc(t.key),money(t.net/100)]))}</div><div class="panel" style="overflow:auto"><h3>Historique des imports</h3>${table(['Fichier','Boutique','Date','Transactions','Actions'],reports.map(r=>[esc(r.fileName),esc(r.storeName),esc(r.createdAt),r.transactions.length,canManageJumia()?`<button class="danger" data-jumia-toggle="jumiaReports/${r.id}">Désactiver</button>`:'']))}</div>`;
}
document.addEventListener('change',e=>{if(e.target.id==='jumia-import-store'){jumiaImportStore=e.target.value;jumiaImportReport='';render();}if(e.target.id==='jumia-import-report'){jumiaImportReport=e.target.value;render();}});
let jumiaReportUpdateRequest=null,jumiaReportUpdatePreview=null,jumiaReportUpdateRevision=0;
async function commitJumiaReportUpdate(request,preview){const result=await api('jumiaReports',{...request,action:'commitUpdate',expectedToken:preview.token});jumiaReportUpdateRequest=jumiaReportUpdatePreview=null;jumiaImportStore=String(request.storeId);jumiaImportReport=String(result.id);await load();}
document.addEventListener('change',e=>{if(e.target.form?.id!=='jumia-import-form')return;jumiaReportUpdateRevision++;jumiaReportUpdateRequest=jumiaReportUpdatePreview=null;const target=$('#jumia-report-update-preview');if(target)target.innerHTML='';});
document.addEventListener('submit',async e=>{if(e.target.id!=='jumia-import-form')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,button=form.querySelector('button'),error=$('#jumia-import-error'),revision=++jumiaReportUpdateRevision;button.disabled=true;error.textContent='';jumiaReportUpdateRequest=jumiaReportUpdatePreview=null;$('#jumia-report-update-preview').innerHTML='';try{const file=form.elements.csvFile.files[0];if(!file)throw Error('Choisissez un CSV');if(file.size>2*1024*1024)throw Error('CSV : maximum 2 Mo');const request={storeId:Number(form.elements.storeId.value),fileName:file.name,csv:await file.text()},preview=await api('jumiaReports',{...request,action:'previewUpdate'});if(revision!==jumiaReportUpdateRevision)return;if(!preview.replacement){await commitJumiaReportUpdate(request,preview);return;}jumiaReportUpdateRequest=request;jumiaReportUpdatePreview=preview;$('#jumia-report-update-preview').innerHTML=`<h3>Actualisation du relevé — ${esc(preview.storeName)}</h3>${table(['Relevé','Ancien net','Nouveau net','Écart','Transactions avant / après','Ajoutées / modifiées / retirées'],preview.rows.map(r=>[esc(r.number),money(r.oldNetCents/100),money(r.newNetCents/100),money(r.differenceCents/100),r.oldCount+' / '+r.newCount,r.added+' / '+r.changed+' / '+r.removed]))}<p>Le CSV remplacera toutes les transactions des relevés indiqués, y compris les montants et statuts PAID. Vérifiez qu’il contient la version complète. Les autres relevés restent conservés. La version précédente est conservée dans l’historique. Aucun virement bancaire n’est créé.</p><button type="button" id="jumia-report-update-confirm">Remplacer et recalculer</button><button type="button" class="secondary" id="jumia-report-update-cancel">Annuler</button>`;}catch(err){error.textContent=err.message;}finally{button.disabled=false;}},true);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='jumia-report-update-cancel'){jumiaReportUpdateRequest=jumiaReportUpdatePreview=null;$('#jumia-report-update-preview').innerHTML='';}if(b.id==='jumia-report-update-confirm'&&jumiaReportUpdateRequest&&jumiaReportUpdatePreview){b.disabled=true;try{await commitJumiaReportUpdate(jumiaReportUpdateRequest,jumiaReportUpdatePreview);}catch(error){$('#jumia-import-error').textContent=error.message;}finally{b.disabled=false;}}});


function renderJumiaComparison(c){const optional=n=>n===null?'À vérifier':money(n/100);return `<div class="panel" style="overflow:auto"><h3>Par SKU vendeur — marge sur achat</h3><p>${c.matched} rapprochements · ${c.missing} à vérifier. Marge = net Jumia − coût d’achat de la saisie. Marge / achat (%) = marge ÷ coût d’achat. Transport et emballage exclus. Quantité : articles uniques crédités dans le relevé.</p>${table(['Boutique','SKU vendeur','Qté créditée','Ventes créditées','Frais nets','Net Jumia','Coût d’achat','Marge sur achat','Marge / achat %','Écart ventes / saisie','Rapprochement'],c.skus.map(g=>[esc(g.storeName),esc(g.sku),g.qty,money(g.sales/100),money((g.sales-g.net)/100),money(g.net/100),g.missing?'À vérifier':money(g.cost/100),g.missing?'À vérifier':money(g.margin/100),g.rate===null?'—':g.rate.toFixed(2)+' %',g.missing?'À vérifier':money(g.difference/100),g.missing?g.missing+' rapprochement(s) manquant(s)':'Complet']))}</div><div class="panel" style="overflow:auto"><h3>Comparaison avec les commandes saisies</h3>${table(['Boutique','Commande','SKU vendeur','Qté créditée','Ventes saisies','Ventes Jumia','Écart ventes','Coût d’achat','Marge','État'],c.details.map(d=>[esc(d.storeName),esc(d.order),esc(d.sku),d.qty,optional(d.entered),money(d.sales/100),optional(d.difference),optional(d.cost),optional(d.margin),esc(d.status)]))}</div><div class="panel" style="overflow:auto"><h3>Écarts frais Jumia et net</h3><p>Écart net = net du relevé − net de la saisie. Un montant positif signifie que la saisie déduit davantage de frais ou compte moins de ventes livrées. Une quantité partiellement créditée reste à vérifier pour comparer les frais totaux.</p>${table(['Commande','SKU vendeur','Commission saisie','Commission Jumia','Écart commission','Shipping saisi','Shipping Jumia','Écart shipping','Autres frais saisis','Autres frais Jumia','Net saisi','Net Jumia','Écart net'],c.details.map(d=>[esc(d.order),esc(d.sku),optional(d.enteredCommission),money(d.commission/100),optional(d.enteredCommission===null?null:d.commission-d.enteredCommission),optional(d.enteredShipping),money(d.shipping/100),optional(d.enteredShipping===null?null:d.shipping-d.enteredShipping),optional(d.enteredOther),money(d.other/100),optional(d.enteredNet),money(d.net/100),optional(d.netDifference)]))}<p><strong>Écart net total des lignes comparables : ${money(c.details.reduce((sum,d)=>sum+(d.netDifference??0),0)/100)}</strong>${c.details.some(d=>d.netDifference===null)?' — comparaison incomplète, vérifiez les lignes manquantes.':''}</p></div>`;}
let jumiaOrderImportPreview=null,jumiaOrderImportRequest=null,jumiaOrderImportRevision=0;
function jumiaReturnsMarkup(preview){return preview.orders.filter(o=>o.returns?.length).map(o=>`<fieldset data-return-order="${esc(o.number)}"><legend>Retour commande ${esc(o.number)}</legend>${o.newReturn?'<p>Commande absente de la saisie : elle sera créée directement en Retourné après votre confirmation, sans nouveau produit stock.</p>':`<label><input type="checkbox" data-confirm-return="${esc(o.number)}"> Je confirme le passage des articles livrés concernés à Retourné.</label>`}<p>Confirmez chaque article avant l’enregistrement. Seuls les articles retournés changent de statut. Un produit utilisable revient au stock ; un produit endommagé conserve son coût d’achat en perte. L’indemnisation réduit la perte. Transport retour : 20 DH par défaut, en plus du transport aller, du ticket et du carton. Sel exclu si tous les articles sont échoués ou retournés.</p>${o.returns.map(r=>`<div data-jumia-return="${esc(r.key)}"><h4>${esc(r.sku)} — ${esc(r.name)} · Quantité ${r.qty} · Coût d’achat ${money(r.purchaseCost)}</h4><label>État confirmé du produit<select data-return-condition required><option value="">Choisir après vérification</option><option value="usable">Utilisable — remettre au stock</option><option value="damaged">Endommagé / inutilisable — perte du coût d’achat</option></select></label><label>Indemnisation Jumia totale (MAD)<input data-return-compensation type="number" min="0" step="0.01" value="0" required></label><p>0 = aucun remboursement. Saisissez le montant réel si Jumia indemnise tout ou partie.</p></div>`).join('')}</fieldset>`).join('');}
function captureJumiaReturnDecisions(){const selected=new Set(selectedJumiaImportOrders()),decisions={};for(const row of document.querySelectorAll('[data-jumia-return]')){if(!selected.has(row.closest('[data-return-order]').dataset.returnOrder))continue;const condition=row.querySelector('[data-return-condition]').value,raw=row.querySelector('[data-return-compensation]').value;if(!condition)throw Error('Confirmez si chaque produit retourné est utilisable ou endommagé');if(raw==='')throw Error('Indiquez l’indemnisation, ou 0 sans indemnisation');decisions[row.dataset.jumiaReturn]={condition,compensation:Number(raw)};}return decisions;}
function jumiaImportStatusMarkup(order){return order.status==='Retour à confirmer'?`<button type="button" class="secondary" data-open-import-return="${esc(order.number)}">Confirmer le retour</button>`:esc(order.status);}
function showJumiaOrderImportError(message){const modalError=$('#jumia-dialog')?.open?$('#jumia-return-error'):null;for(const node of [$('#jumia-orders-import-error'),$('#jumia-orders-import-message'),modalError])if(node)node.textContent=message;const node=modalError||$('#jumia-orders-import-message')||$('#jumia-orders-import-error');node?.scrollIntoView?.({block:'center',behavior:'smooth'});node?.focus?.();}
function validateJumiaReturnPanel(panel){const confirmation=panel.querySelector('[data-confirm-return]');if(confirmation&&!confirmation.checked)throw Error('Confirmez le passage des articles livrés à Retourné.');for(const row of panel.querySelectorAll('[data-jumia-return]')){const condition=row.querySelector('[data-return-condition]'),input=row.querySelector('[data-return-compensation]'),amount=Number(input.value);if(!['usable','damaged'].includes(condition.value)){condition.focus();throw Error('Choisissez si le produit est utilisable ou endommagé.');}if(input.value===''||!Number.isFinite(amount)||amount<0||!Number.isSafeInteger(Math.round(amount*100))||Math.abs(amount*100-Math.round(amount*100))>0.00001){input.focus();throw Error('Saisissez une indemnisation valide, ou 0 sans indemnisation.');}}}
function openJumiaImportReturn(number){
 const checkbox=[...document.querySelectorAll('[data-import-order]')].find(input=>input.dataset.importOrder===number),panel=[...document.querySelectorAll('[data-return-order]')].find(node=>node.dataset.returnOrder===number),dialog=$('#jumia-dialog');
 if(!checkbox||checkbox.disabled||!panel){showJumiaOrderImportError('Prévisualisez de nouveau le fichier pour confirmer ce retour.');return;}
 if(dialog.open)return;const wasChecked=checkbox.checked;checkbox.checked=true;updateJumiaImportSelection();
 const parent=panel.parentNode,next=panel.nextSibling,fields=[...panel.querySelectorAll('input,select')].map(input=>({input,value:input.value,checked:input.checked}));let accepted=false;
 dialog.innerHTML=`<h2>Confirmer le retour — commande ${esc(number)}</h2><div id="jumia-return-panel"></div><p id="jumia-return-error" role="alert" tabindex="-1"></p><p>Cette validation prépare le retour. Le stock change uniquement après confirmation de l’import des commandes sélectionnées.</p><button type="button" id="jumia-return-accept">Valider les informations du retour</button><button type="button" class="secondary" data-close-jumia>Annuler</button>`;
 $('#jumia-return-panel').appendChild(panel);panel.hidden=false;
 dialog.addEventListener('close',()=>{if(!accepted){checkbox.checked=wasChecked;for(const field of fields){field.input.value=field.value;field.input.checked=field.checked;}}if(parent.isConnected){if(next?.parentNode===parent)parent.insertBefore(panel,next);else parent.appendChild(panel);panel.hidden=!checkbox.checked;}updateJumiaImportSelection();const trigger=[...document.querySelectorAll('[data-open-import-return]')].find(button=>button.dataset.openImportReturn===number);if(trigger&&accepted)trigger.textContent='Retour renseigné — modifier';}, {once:true});
 $('#jumia-return-accept').addEventListener('click',()=>{try{validateJumiaReturnPanel(panel);accepted=true;dialog.close();const message=$('#jumia-orders-import-message')||$('#delegate-import-error');if(message)message.textContent='Retour '+number+' renseigné. Confirmez maintenant l’import des commandes sélectionnées.';}catch(error){showJumiaOrderImportError(error.message);}});
 dialog.showModal();
}
document.addEventListener('click',e=>{const button=e.target.closest('[data-open-import-return]');if(button)openJumiaImportReturn(button.dataset.openImportReturn);});
function selectedJumiaImportOrders(){return [...document.querySelectorAll('[data-import-order]:checked')].map(e=>e.dataset.importOrder);}
function updateJumiaImportSelection(){const selected=new Set(selectedJumiaImportOrders());const count=$('#jumia-import-selection-count');if(count)count.textContent=selected.size+' commande(s) sélectionnée(s)';for(const panel of document.querySelectorAll('[data-return-order]'))panel.hidden=!selected.has(panel.dataset.returnOrder);const button=$('#jumia-orders-import-commit');if(button){button.disabled=!selected.size;button.textContent='Confirmer et enregistrer '+selected.size+' commande(s)';}}
document.addEventListener('change',e=>{if(e.target.hasAttribute?.('data-import-order'))updateJumiaImportSelection();});
document.addEventListener('click',e=>{const button=e.target.closest('#jumia-import-select-all, #jumia-import-select-none');if(!button)return;for(const box of document.querySelectorAll('[data-import-order]:not(:disabled)'))box.checked=button.id==='jumia-import-select-all';updateJumiaImportSelection();});
function orderImportMarkup(){return `<div class="panel"><h3>Importer des commandes Jumia</h3><p>Les numéros de commande sont vérifiés avec les IDs des relevés paiements enregistrés. Le CSV commandes ne contient généralement pas d’ID boutique : pour les commandes absentes des relevés, vérifiez la boutique avant confirmation. Les SKU Jumia sont aussi comparés aux listings : un SKU connu uniquement dans une autre boutique bloque l’import. Les SKU absents des listings restent acceptés ; un SKU partagé entre boutiques demande une vérification manuelle.</p><form id="jumia-orders-import-form"><label>Boutique<select name="storeId" required><option value="">Choisir</option>${state.jumiaStores.filter(s=>s.active!==false).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>Export commandes CSV (2 Mo maximum)<input name="csvFile" type="file" accept=".csv,text/csv" required></label><button>Prévisualiser</button><p id="jumia-orders-import-error" role="alert"></p></form><div id="jumia-orders-import-preview"></div><p>Le hub est identifié par Shipment Provider / Shipping Provider si son code est enregistré dans Hubs. Un code non associé est affiché dans la prévisualisation, sans choix automatique de hub. Chaque ligne du fichier représente un article. Unit Price est utilisé pour la vente. Paid Price et Shipping Fee client ne remplacent pas les frais du relevé financier. Les commandes déjà saisies sont rapprochées pour mettre à jour statuts et dates, sans dupliquer le stock. Les retours sont rapprochés des articles livrés et demandent confirmation de l’état du produit et de l’indemnisation. Les statuts du CSV sont conservés. Les articles expédiés, livrés ou échoués sortent du stock, même si le stock devient négatif. Une livraison échouée remet automatiquement les articles en stock. Les listings absents sont créés sans nouveau produit stock. Reliez les listings non reconnus à vos produits dans Listings → Modifier ; le coût d’achat et le stock seront alors recalculés.</p></div>`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='jumia-orders-import-form')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,button=form.querySelector('button'),revision=++jumiaOrderImportRevision;button.disabled=true;jumiaOrderImportPreview=null;$('#jumia-orders-import-preview').innerHTML='';try{const file=form.elements.csvFile.files[0];if(file&&file.size>2*1024*1024)throw Error('CSV : maximum 2 Mo');jumiaOrderImportRequest={storeId:Number(form.elements.storeId.value),fileName:file.name,csv:await file.text()};const preview=await api('jumiaOrderImports',{...jumiaOrderImportRequest,action:'preview'});if(revision!==jumiaOrderImportRevision)return;jumiaOrderImportPreview=preview;$('#jumia-orders-import-error').textContent='';$('#jumia-orders-import-preview').innerHTML=`<h3>Destination : ${esc(preview.storeName)}</h3><p>ID Jumia : ${esc(preview.identity?.statementStoreId||'Non renseigné')} · ${preview.identity?.verifiedOrders||0} commande(s) vérifiée(s) par Statement Number · ${preview.identity?.unverifiedOrders||0} commande(s) sans relevé correspondant.</p><p>Vérification listings par SKU Jumia : ${preview.identity?.listingVerifiedOrders||0} commande(s) entièrement rapprochée(s) · ${preview.identity?.listingPartialOrders||0} partiellement rapprochée(s). SKU inconnus : ${esc((preview.identity?.unknownJumiaSkus||[]).join(', ')||'Aucun')}. SKU présents dans plusieurs boutiques (à vérifier) : ${esc((preview.identity?.ambiguousJumiaSkus||[]).join(', ')||'Aucun')}. La boutique destination reste à confirmer avant import.</p><p>Fichier : ${esc(preview.fileName)} · ${preview.orders.length} commande(s). ${preview.unknownSkus.length} SKU nouveau(x) accepté(s), listings créés à l’import. Le CSV ne garantit pas le nom de la boutique : vérifiez votre export Seller Center.</p><button type="button" id="jumia-import-select-all" class="secondary">Tout sélectionner</button><button type="button" id="jumia-import-select-none" class="secondary">Tout désélectionner</button><p id="jumia-import-selection-count"></p>${table(['Sélection','Commande','Shipping Provider / Hub','Articles','Montant articles','Statuts CSV','Statuts enregistrés','État import','À corriger'],preview.orders.map(o=>[`<input type="checkbox" data-import-order="${esc(o.number)}" aria-label="Importer commande ${esc(o.number)}" ${['Nouvelle','À mettre à jour','Client à compléter','Retour à confirmer'].includes(o.status)?'checked':'disabled'}>`,esc(o.number),esc(o.body.shippingProviderCode||'Non renseigné')+'<br>'+esc(o.body.hubName||o.hubWarning||'Hub non identifié'),o.qty,money(o.body.lines.reduce((sum,l)=>sum+l.qty*l.salePrice,0)),[...new Set(o.body.lines.map(l=>l.status))].map(esc).join('<br>'),(o.existingStatuses||[]).map(esc).join('<br>')||'Non enregistrée',jumiaImportStatusMarkup(o),[...o.errors,...o.body.lines.filter(l=>l.needsLink||l.createListing).map(l=>l.sku+' : '+(l.needsLink?'listing à relier au produit stock':'nouveau listing'))].map(esc).join('<br>')]))}<p>Frais internes par nouvelle commande : transport hub 20 DH, ticket 1 DH, sel 2 DH, carton 2 DH. Modifiez-les ensuite dans la commande si nécessaire.</p>${jumiaReturnsMarkup(preview)}<p id="jumia-orders-import-message" role="alert" tabindex="-1"></p><div class="confirmation-actions"><label><input type="checkbox" id="jumia-import-confirm-store"> Je confirme que ce fichier vient de ${esc(preview.storeName)}.</label>${preview.orders.some(o=>['Nouvelle','À mettre à jour','Client à compléter','Retour à confirmer'].includes(o.status))?'<button type="button" id="jumia-orders-import-commit">Confirmer et enregistrer la sélection</button>':''}</div>`;updateJumiaImportSelection();}catch(err){$('#jumia-orders-import-error').textContent=err.message;}finally{button.disabled=false;}},true);
document.addEventListener('click',async e=>{const button=e.target.closest('#jumia-orders-import-commit');if(!button)return;button.disabled=true;try{if(!$('#jumia-import-confirm-store')?.checked)throw Error('Confirmez que le fichier vient de '+jumiaOrderImportPreview.storeName);const selectedOrders=selectedJumiaImportOrders();if(!selectedOrders.length)throw Error('Sélectionnez au moins une commande');const confirmedReturns=[...document.querySelectorAll('[data-confirm-return]:checked')].map(e=>e.dataset.confirmReturn);for(const order of jumiaOrderImportPreview.orders.filter(o=>selectedOrders.includes(o.number)&&o.returns?.length&&!o.newReturn)){if(!confirmedReturns.includes(order.number)){openJumiaImportReturn(order.number);throw Error('Confirmez le passage de Livré à Retourné pour '+order.number);}}for(const number of selectedOrders){const panel=[...document.querySelectorAll('[data-return-order]')].find(p=>p.dataset.returnOrder===number);if(panel){try{validateJumiaReturnPanel(panel);}catch(error){openJumiaImportReturn(number);throw error;}}}const returnDecisions=captureJumiaReturnDecisions();const result=await api('jumiaOrderImports',{...jumiaOrderImportRequest,confirmedStoreId:jumiaOrderImportRequest.storeId,selectedOrders,confirmedReturns,returnDecisions,action:'commit',expectedPreview:JSON.stringify(jumiaOrderImportPreview)});jumiaOrderImportPreview=null;jumiaOrderImportRequest=null;await load();$('#notice').textContent=(result.updated||0)+' commande(s) mise(s) à jour, '+(result.returnsUpdated||0)+' retour(s) confirmé(s), '+result.count+' commande(s) importée(s), '+(result.clientsUpdated||0)+' client(s) complété(s), '+(result.listingsCreated||0)+' listing(s) ajouté(s).';}catch(err){showJumiaOrderImportError(err.message);button.disabled=false;}});

function categorySelect(name,id){return `<label>Catégorie<select name="${name}"><option value="">Sans catégorie</option>${(state.jumiaCategories||[]).filter(c=>c.active!==false||c.id===id).map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.code?c.code+' — '+c.name:c.name)}</option>`).join('')}</select></label>`;}
function jumiaCategoryEditor(record){jumiaEditor={kind:'jumiaCategories',record};const dialog=$('#jumia-dialog');dialog.innerHTML=`<h2>${record?'Modifier':'Ajouter'} une catégorie</h2><form id="jumia-category-form">${field('name','Nom de la catégorie','text',record?.name)}${record?field('reason','Motif obligatoire'):''}<button>Enregistrer</button><button type="button" class="secondary" data-close-jumia>Annuler</button></form><p id="jumia-error" role="alert"></p>`;dialog.showModal();}
document.addEventListener('change',e=>{if(e.target.id==='jumia-listing-category'){jumiaListingCategory=e.target.value;render();}});

let brandSearchResults=[],brandTotal=null,brandEdit=null,brandQuery='',brandOffset=0,brandMatched=0,brandLoaded=false,brandLoading=false;const brandChoices=new Map();let brandSearchTimer;
function brandPicker(name,id=null,label='',code=''){return `<label>Brand (recherche : 3 caractères)<input data-brand-picker="${name}" list="brands-${name}" value="${esc(label?(label+(code?' ['+code+']':'')):'')}" autocomplete="off"><input type="hidden" name="${name}" value="${id||''}"><datalist id="brands-${name}"></datalist></label>`;}
function renderBrands(){if(!brandLoaded&&!brandLoading)loadBrandCatalogue().catch(error=>{$('#notice').textContent=error.message;});const assigned=new Map();for(const store of state.jumiaStores)for(const listing of store.listings||[])if(listing.brandId){const brand=assigned.get(listing.brandId)||{id:listing.brandId,code:listing.brandCode||'',name:listing.brandName||'Brand #'+listing.brandId,count:0};brand.count++;assigned.set(brand.id,brand);}return `<div class="panel"><h3>Brands Jumia${brandTotal===null?'':' — '+brandTotal}</h3><form id="brand-import-form"><label>CSV brands Jumia (8 Mo maximum)<input type="file" name="file" accept=".csv,text/csv" required></label><button>Importer la liste</button></form><h3>Brands de mes listings</h3>${table(['Code','Brand','Listings'],[...assigned.values()].sort((a,b)=>a.name.localeCompare(b.name)).map(b=>[esc(b.code||'—'),esc(b.name),b.count]))}<h3>Catalogue des brands</h3><form id="brand-search-form"><label>Recherche par nom ou code (3 caractères)<input name="q" minlength="3" value="${esc(brandQuery)}" placeholder="Tous les brands si vide"></label><button>Rechercher</button></form>${brandLoading?'<p>Chargement des brands…</p>':''}${table(['Code','Brand','État','Actions'],brandSearchResults.map(b=>[esc(b.code||'—'),esc(b.name),b.active?'Actif':'Désactivé',state.currentUser.role!=='jumia_delegate'||b.delegateEditable?`<button class="secondary" data-brand-edit="${b.id}">Modifier</button>`:'Catalogue partagé']))}<div class="toolbar"><button id="brand-prev" class="secondary" ${brandOffset===0||brandLoading?'disabled':''}>Précédent</button><span>${brandMatched?brandOffset+1:0}–${Math.min(brandOffset+50,brandMatched)} / ${brandMatched}</span><button id="brand-next" class="secondary" ${brandOffset+50>=brandMatched||brandLoading?'disabled':''}>Suivant</button></div><button id="brand-add">Ajouter un brand</button><p id="brand-error" role="alert"></p></div>`;}
function brandEditor(record){brandEdit=record;const d=$('#jumia-dialog');d.innerHTML=`<h2>${record?'Modifier':'Ajouter'} un brand</h2><form id="brand-edit-form">${record?'':field('code','Code Jumia (facultatif)')}${field('name','Nom','text',record?.name)}<label>État<select name="active"><option value="true">Actif</option><option value="false" ${record&&!record.active?'selected':''}>Désactivé</option></select></label><button>Enregistrer</button><button type="button" data-close-jumia class="secondary">Annuler</button></form><p id="jumia-error" role="alert"></p>`;d.showModal();}
document.addEventListener('input',e=>{const name=e.target.dataset.brandPicker;if(!name)return;const input=e.target,hidden=input.parentElement.querySelector('input[type=hidden]'),q=input.value.trim();hidden.value=brandChoices.get(q)?.id||'';clearTimeout(brandSearchTimer);if(q.length<3){$('#brands-'+name).innerHTML='';return;}brandSearchTimer=setTimeout(async()=>{try{const r=await fetch('/api/jumiaBrands?q='+encodeURIComponent(q));if(!r.ok)throw Error('Recherche brand impossible');const data=await r.json();if(input.value.trim()!==q)return;$('#brands-'+name).innerHTML=data.rows.filter(b=>b.active).map(b=>{const label=b.name+(b.code?' ['+b.code+']':'');brandChoices.set(label,b);return `<option value="${esc(label)}"></option>`;}).join('');}catch(err){$('#notice').textContent=err.message;}},200);});
document.addEventListener('change',e=>{if(e.target.id==='jumia-listing-brand-filter'){jumiaListingBrand=e.target.value.trim();render();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.id==='brand-add')brandEditor(null);if(b?.dataset.brandEdit)brandEditor(brandSearchResults.find(x=>x.id===Number(b.dataset.brandEdit)));});
document.addEventListener('submit',async e=>{if(!['brand-import-form','brand-search-form','brand-edit-form'].includes(e.target.id))return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,b=form.querySelector('button');b.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(form.id==='brand-search-form'){brandQuery=data.q.trim();brandOffset=0;await loadBrandCatalogue();}else if(form.id==='brand-import-form'){const file=form.elements.file.files[0];if(!file||file.size>8*1024*1024)throw Error('CSV : maximum 8 Mo');const result=await api('jumiaBrands',{action:'import',csv:await file.text()});brandQuery='';brandOffset=0;await loadBrandCatalogue();$('#notice').textContent=result.count+' brands importés. Les codes existants ont été mis à jour.';}else{data.active=data.active==='true';if(brandEdit){data.id=brandEdit.id;data.expectedRecord=JSON.stringify(brandEdit);}await api('jumiaBrands',data);$('#jumia-dialog').close();await loadBrandCatalogue();}}catch(err){const error=form.id==='brand-edit-form'?$('#jumia-error'):$('#brand-error');error.textContent=err.message;}finally{b.disabled=false;}},true);

function readBrandId(form,name){const hidden=form.elements[name],input=form.querySelector('[data-brand-picker="'+name+'"]');if(input?.value.trim()&&!hidden.value)throw Error('Sélectionnez un brand dans les suggestions');return Number(hidden.value)||null;}

async function loadBrandCatalogue(){brandLoading=true;try{const r=await fetch('/api/jumiaBrands?q='+encodeURIComponent(brandQuery)+'&offset='+brandOffset);if(!r.ok)throw Error('Chargement des brands impossible');const data=await r.json();brandSearchResults=data.rows;brandTotal=data.total;brandMatched=data.matched;brandLoaded=true;}finally{brandLoading=false;}if(page==='jumiaBrands')render();}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||!['brand-prev','brand-next'].includes(b.id)||brandLoading)return;brandOffset=Math.max(0,brandOffset+(b.id==='brand-next'?50:-50));try{await loadBrandCatalogue();}catch(error){$('#notice').textContent=error.message;}});

const listingProductChoices=new Map();
document.addEventListener('input',e=>{if(e.target.id!=='jumia-listing-product-search')return;const form=e.target.form,q=e.target.value.trim(),selected=listingProductChoices.get(q);form.elements.productId.value=selected?.id||'';if(selected){form.elements.commissionPercent.value=selected.jumiaCommissionPercent??state.jumiaStores.find(s=>s.id===Number(form.dataset.storeId))?.commissionPercent??0;form.elements.salePriceHT.value=selected.price??0;form.elements.salePrice.value=selected.price??0;}const normalized=normalizeProductName(q);const matches=q.length>=3?jumiaProducts().filter(p=>p.active!==false&&(normalizeProductName(p.name).includes(normalized)||String(p.barcode||'').includes(q)||String(p.sku||'').toLowerCase().includes(q.toLowerCase()))).slice(0,30):[];$('#jumia-listing-product-options').innerHTML=matches.map(p=>{const label=p.name+' ['+(p.barcode||p.sku||p.id)+']';listingProductChoices.set(label,p);return `<option value="${esc(label)}"></option>`;}).join('');});

document.addEventListener('submit',async e=>{if(e.target.id!=='jumia-category-import-form')return;e.preventDefault();e.stopImmediatePropagation();const button=e.target.querySelector('button');button.disabled=true;try{const file=e.target.elements.file.files[0];if(file&&file.size>2*1024*1024)throw Error('CSV : maximum 2 Mo');const bytes=await file.arrayBuffer();let csv;try{csv=new TextDecoder('utf-8',{fatal:true}).decode(bytes);}catch{csv=new TextDecoder('windows-1252').decode(bytes);}const result=await api('jumiaCategories',{action:'import',csv});await load();$('#notice').textContent=result.created+' catégories ajoutées, '+result.updated+' mises à jour.';}catch(error){$('#jumia-category-import-error').textContent=error.message;}finally{button.disabled=false;}},true);

let catalogRequest=null,catalogPreview=null,catalogRevision=0,catalogRowBusy=false;
function catalogImportMarkup(storeId=null){return `<div class="panel"><h3>Importer listings (Excel Jumia)</h3><form id="jumia-catalog-import-form">${storeId?`<input type="hidden" name="storeId" value="${storeId}">`:`<label>Boutique<select name="storeId" required><option value="">Choisir</option>${state.jumiaStores.filter(s=>s.active!==false).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label>`}<label>Catalogue .xlsx (8 Mo)<input type="file" name="file" accept=".xlsx" required></label><button>Prévisualiser</button><button type="button" id="catalog-cancel" class="secondary">Annuler</button></form><p id="jumia-catalog-error" role="alert" aria-live="polite"></p><p>Seuls les listings sont ajoutés. Aucun produit stock n’est créé. Créez votre produit dans Articles, puis reliez-le au listing avec Modifier.</p><div id="jumia-catalog-preview" aria-live="polite"></div></div>`;}
async function previewCatalogImport(){const revision=catalogRevision,request=catalogRequest;const preview=await api('jumiaCatalogImports',{...request,action:'preview'});if(revision!==catalogRevision)return;catalogPreview=preview;$('#jumia-catalog-preview').innerHTML=`<h3>${esc(preview.storeName)} — ${preview.rows.length} listings${catalogRequest.fileName?' · '+esc(catalogRequest.fileName):''}</h3><div style="overflow:auto">${table(['SKU vendeur','Désignation','Produit stock / correspondance','État','À corriger','Enregistrer'],preview.rows.map(r=>[esc(r.sku),esc(r.name),r.status==='Listing existant — ignoré'?'Existant':`<select data-catalog-match="${esc(r.sku)}"><option value="0">À relier plus tard au stock</option>${jumiaProducts().filter(p=>p.active!==false).map(p=>`<option value="${p.id}" ${p.id===r.productId?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`,esc(r.status),esc(r.error),r.status==='Listing existant — ignoré'?'—':`<button type="button" data-catalog-save-row="${esc(r.sku)}">Enregistrer</button><p data-catalog-row-message role="status"></p>`]))}</div><button type="button" id="catalog-repreview" class="secondary">Recalculer la prévisualisation</button>${preview.rows.some(r=>r.status!=='Listing existant — ignoré')&&!preview.rows.some(r=>r.error)?'<button type="button" id="catalog-commit">Enregistrer les listings</button>':''}`;}
function resetCatalogImport(clearFile=false){catalogRevision++;catalogRequest=null;catalogPreview=null;const form=$('#jumia-catalog-import-form');if(clearFile&&form)form.elements.file.value='';if(form){const button=form.querySelector('button');button.disabled=false;button.textContent='Prévisualiser';}$('#jumia-catalog-preview').innerHTML='';$('#jumia-catalog-error').textContent='';}
document.addEventListener('change',e=>{if(e.target.form?.id==='jumia-catalog-import-form'&&e.target.name==='file')resetCatalogImport();});
document.addEventListener('click',e=>{if(e.target.closest('#catalog-cancel'))resetCatalogImport(true);});
document.addEventListener('submit',async e=>{if(e.target.id!=='jumia-catalog-import-form')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,button=form.querySelector('button'),label='Prévisualiser',revision=++catalogRevision;button.disabled=true;button.textContent='Lecture du fichier…';catalogRequest=null;catalogPreview=null;$('#jumia-catalog-preview').innerHTML='';$('#jumia-catalog-error').textContent='';try{const file=form.elements.file.files[0];if(!file||file.size>8*1024*1024)throw Error('Choisissez un fichier Excel .xlsx de 8 Mo maximum');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Impossible de lire le fichier Excel. Sélectionnez-le à nouveau.'));reader.onabort=()=>reject(Error('Lecture du fichier annulée'));reader.readAsDataURL(file);});if(revision!==catalogRevision)return;catalogRequest={storeId:Number(form.elements.storeId.value),base64,productMatches:{},fileName:file.name};button.textContent='Prévisualisation en cours…';await previewCatalogImport();if(revision!==catalogRevision)return;if(!catalogPreview.rows.length)$('#jumia-catalog-error').textContent='Aucun produit trouvé dans ce fichier.';}catch(err){if(revision!==catalogRevision)return;catalogPreview=null;$('#jumia-catalog-error').textContent=err.message||'La prévisualisation a échoué. Réessayez.';}finally{if(revision===catalogRevision){button.disabled=false;button.textContent=label;}}},true);
document.addEventListener('change',e=>{if(e.target.dataset.catalogMatch){catalogRequest.productMatches[e.target.dataset.catalogMatch]=Number(e.target.value);catalogPreview=null;const button=$('#catalog-commit');if(button)button.disabled=true;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||catalogRowBusy||!['catalog-repreview','catalog-commit'].includes(b.id))return;b.disabled=true;try{if(b.id==='catalog-repreview'){await previewCatalogImport();return;}if(!catalogPreview)throw Error('Recalculez la prévisualisation');const result=await api('jumiaCatalogImports',{...catalogRequest,action:'commit',expectedPreview:JSON.stringify(catalogPreview)});catalogPreview=null;catalogRequest=null;await load();$('#notice').textContent=result.listingsCreated+' listings ajoutés. Reliez les listings à vos produits stock.';}catch(err){$('#jumia-catalog-error').textContent=err.message;}finally{b.disabled=false;}});

let jumiaClientStore='',jumiaClientSearch='',jumiaClientStatus='';
function filteredJumiaCustomers(applyStatus=true){return jumiaCustomers(state.jumiaOrders.filter(o=>!jumiaClientStore||String(o.storeId)===jumiaClientStore)).filter(c=>!jumiaClientSearch||[c.name,c.address,...c.orders.map(o=>o.number)].join(' ').toLowerCase().includes(jumiaClientSearch.toLowerCase())).filter(c=>!applyStatus||!jumiaClientStatus||(jumiaClientStatus==='pending'?c.pendingOrders>0:jumiaClientStatus==='shipped'?c.shippedOrders>0:jumiaClientStatus==='delivered'?c.deliveredOrders>0:jumiaClientStatus==='returned'?c.returnedOrders>0:jumiaClientStatus==='cancelled'?c.cancelledOrders>0:c.failedOrders>0));}
function renderJumiaClients(){const customers=filteredJumiaCustomers(),all=filteredJumiaCustomers(false);return `<div class="panel"><h3>Clients Jumia</h3><form id="jumia-client-filters"><label>Boutique<select name="store"><option value="">Toutes les boutiques</option>${state.jumiaStores.map(s=>`<option value="${s.id}" ${String(s.id)===jumiaClientStore?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${field('search','Client / adresse / commande','text',jumiaClientSearch)}<button>Rechercher</button></form><div class="jumia-status-tabs">${[['','Tous les clients',all.length],['pending','Clients avec commandes en attente',all.filter(c=>c.pendingOrders>0).length],['shipped','Clients avec commandes expédiées',all.filter(c=>c.shippedOrders>0).length],['delivered','Clients avec commandes livrées',all.filter(c=>c.deliveredOrders>0).length],['returned','Clients avec retours',all.filter(c=>c.returnedOrders>0).length],['failed','Clients avec livraison échouée',all.filter(c=>c.failedOrders>0).length],['cancelled','Clients avec annulations à surveiller',all.filter(c=>c.cancelledOrders>0).length]].map(([value,label,count])=>`<button type="button" data-jumia-client-status="${value}" class="${jumiaClientStatus===value?'':'secondary'}">${label} (${count})</button>`).join('')}</div><p>${customers.length} clients · Un client ayant plusieurs statuts apparaît dans chaque liste concernée. Les clients avec une commande en attente apparaissent en premier. Montant acheté : articles livrés uniquement. Les clients sont regroupés par nom et adresse. Une commande sans nom reste séparée.</p><div class="jumia-client-table">${table(['Client','Adresse','Boutiques','Commandes','En attente','Expédiées','Livrées','Retours','Livraisons échouées','Annulations client ⚠','Annulations vendeur','Montant acheté','Dernier achat','Actions'],customers.map(c=>[esc(c.name),esc(c.address),[...new Set(c.orders.map(o=>o.storeName))].map(esc).join('<br>'),c.orders.length,c.pendingOrders,c.shippedOrders,c.deliveredOrders,c.returnedOrders,c.failedOrders,c.cancelledOrders,c.sellerCancelledOrders,money(c.amount/100),esc(c.lastDate),`<button class="secondary" data-jumia-client="${esc(c.key)}">Voir les achats</button>`]))}</div></div>`;}
document.addEventListener('submit',e=>{if(e.target.id!=='jumia-client-filters')return;e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(e.target));jumiaClientStore=data.store;jumiaClientSearch=data.search.trim();render();},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-jumia-client]');if(!b)return;const client=filteredJumiaCustomers().find(c=>c.key===b.dataset.jumiaClient);if(!client)return;const d=$('#jumia-dialog');d.innerHTML=`<h2>${esc(client.name)}</h2><p>${esc(client.address)}</p>${table(['Commande','Boutique','Date','Articles / statut','Montant livré'],client.orders.map(o=>[esc(o.number),esc(o.storeName),esc(o.date),o.lines.map(l=>esc(l.name)+' × '+l.qty+' — '+esc(l.status)).join('<br>'),money(o.lines.filter(l=>l.status==='Livré').reduce((sum,l)=>sum+l.salePrice*l.qty,0))]))}<button type="button" data-close-jumia>Fermer</button>`;d.showModal();});

document.addEventListener('click',e=>{const button=e.target.closest('[data-jumia-client-status]');if(!button)return;jumiaClientStatus=button.dataset.jumiaClientStatus;render();});

let jumiaPayoutEditor=null;
function jumiaPayoutMarkup(reports){const statements=jumiaStatements(reports),payouts=(state.jumiaPayouts||[]).filter(p=>!jumiaImportStore||String(p.storeId)===jumiaImportStore);return `<div class="panel" style="overflow:auto"><h3>Virements hebdomadaires Jumia</h3><p>Les transactions sont regroupées par numéro de relevé et boutique, avec tous les crédits et débits approuvés. Les annulations et remboursements diminuent le net : aucun second retrait n’est ajouté. Un relevé négatif correspond à un débit à confirmer. Banque par défaut : Attijariwafa bank.</p>${table(['Boutique','Relevé','Semaine','Net crédit / débit','Montant bancaire confirmé','Écart','État','Actions'],statements.map(s=>{const payout=payouts.find(p=>p.active!==false&&p.statementKey===s.key);return [esc(s.storeName),esc(s.number),esc(s.start)+' → '+esc(s.end),money(s.netCents/100),payout?money(payout.amount):'—',payout?money((payout.amountCents-s.netCents)/100):'—',payout?(payout.amountCents<0?'Débit confirmé':'Crédit confirmé'):'À confirmer',canManageJumia()&&s.netCents!==0?`<button class="secondary" data-jumia-payout="${esc(s.key)}">${payout?'Corriger le virement':(s.netCents<0?'Confirmer le débit bancaire':'Confirmer la réception bancaire')}</button>`:'—'];}))}<h3>Historique des virements confirmés</h3>${table(['Date banque','Boutique','Relevé','Banque','Montant bancaire','Référence','État','Actions'],payouts.map(p=>[esc(p.date),esc(p.storeName),esc(p.statementNumber),esc(p.bankName),money(p.amount),esc(p.reference),p.active===false?'Désactivé':'Confirmé',canManageJumia()?`<button class="secondary" data-jumia-payout-toggle="${p.id}">${p.active===false?'Réactiver':'Désactiver'}</button>`:'']))}</div>`;}
function openJumiaPayout(key){const statement=jumiaStatements(state.jumiaReports||[]).find(s=>s.key===key);if(!statement)throw Error('Relevé introuvable');const record=(state.jumiaPayouts||[]).find(p=>p.active!==false&&p.statementKey===key),bank=state.banks.find(b=>b.id===record?.bankId)||state.banks.find(b=>b.active!==false&&/attijari/i.test(b.name));jumiaPayoutEditor={statement,record};const dialog=$('#jumia-dialog');dialog.innerHTML=`<h2>${record?'Corriger':'Confirmer'} le virement Jumia</h2><p>${esc(statement.storeName)} · ${esc(statement.number)} · ${esc(statement.start)} → ${esc(statement.end)}</p><p>Net du relevé : <strong>${money(statement.netCents/100)}</strong>. ${statement.netCents<0?'Confirmez le montant réellement débité par la banque, avec un signe négatif.':'Confirmez le montant réellement crédité par la banque. Les remboursements de ce relevé sont déjà déduits du net.'}</p><form id="jumia-payout-form"><label>Banque<select name="bankId" required><option value="">Choisir</option>${state.banks.filter(b=>b.active!==false).map(b=>`<option value="${b.id}" ${b.id===bank?.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><label>Montant bancaire réel (MAD)<input name="amount" type="number" ${statement.netCents<0?'max="-0.01"':'min="0.01"'} step="0.01" required value="${record?.amount??statement.netCents/100}"></label>${field('date','Date réelle de réception','date',record?.date||chargeDate())}${field('reference','Référence du virement bancaire','text',record?.reference)}${field('reason',record?'Motif de correction obligatoire':'Motif si montant reçu différent du relevé','text',record?.reason)}<p id="jumia-payout-difference"></p><button>${statement.netCents<0?'Confirmer et débiter la banque':'Confirmer et créditer la banque'}</button><button type="button" class="secondary" data-close-jumia>Annuler</button></form><p id="jumia-payout-error" role="alert"></p>`;dialog.showModal();updateJumiaPayoutDifference();}
function updateJumiaPayoutDifference(){const form=$('#jumia-payout-form');if(!form||!jumiaPayoutEditor)return;const amount=Number(form.elements.amount.value),difference=Math.round(amount*100)-jumiaPayoutEditor.statement.netCents;$('#jumia-payout-difference').textContent='Écart reçu / relevé : '+money(difference/100);}
document.addEventListener('input',e=>{if(e.target.form?.id==='jumia-payout-form'&&e.target.name==='amount')updateJumiaPayoutDifference();});
document.addEventListener('click',async e=>{const button=e.target.closest('[data-jumia-payout], [data-jumia-payout-toggle]');if(!button)return;try{if(button.dataset.jumiaPayout){openJumiaPayout(button.dataset.jumiaPayout);return;}const record=state.jumiaPayouts.find(p=>p.id===Number(button.dataset.jumiaPayoutToggle)),reason=prompt('Motif obligatoire');if(!reason?.trim())return;await api('jumiaPayouts',{id:record.id,expectedRecord:JSON.stringify(record),action:'setActive',active:record.active===false,reason});await load();}catch(error){$('#notice').textContent=error.message;}});
document.addEventListener('submit',async e=>{if(e.target.id!=='jumia-payout-form')return;e.preventDefault();e.stopImmediatePropagation();const button=e.target.querySelector('button');button.disabled=true;try{const {statement,record}=jumiaPayoutEditor,data=Object.fromEntries(new FormData(e.target));await api('jumiaPayouts',{...data,bankId:Number(data.bankId),amount:Number(data.amount),statementKey:statement.key,expectedStatement:JSON.stringify(statement),...(record?{id:record.id,expectedRecord:JSON.stringify(record)}:{})});$('#jumia-dialog').close();jumiaPayoutEditor=null;await load();$('#notice').textContent='Virement Jumia confirmé et enregistré dans la banque.';}catch(error){$('#jumia-payout-error').textContent=error.message;}finally{button.disabled=false;}},true);

function jumiaOrderPaymentsMarkup(reports){const payments=jumiaOrderPayments(reports,state.jumiaPayouts||[],state.jumiaOrders||[]);return `<div class="panel" style="overflow:auto"><h3>Commandes et paiements du relevé</h3><p>Rapprochement par boutique et numéro de commande. PAID indique le paiement annoncé par Jumia ; la confirmation bancaire valide l’encaissement. Les montants par commande sont ceux du relevé, avant tout écart bancaire global.</p>${table(['Boutique','Commande','Ventes créditées','Annulations / remboursements produits','Net du relevé','Net dans relevés bancaires confirmés','Paiement','Relevés / dates banque','Actions'],payments.map(p=>[esc(p.storeName),esc(p.number),money(p.salesCents/100),money(p.reversedCents/100),money(p.netCents/100),money(p.bankConfirmedCents/100),esc(p.status),[...new Set(p.transactions.map(t=>t.statement+(t.confirmed?' · '+t.date+' · '+t.bank:' · banque à confirmer')))].map(esc).join('<br>'),p.orderId?`<button class="secondary" data-jumia-view="${p.orderId}">Voir la commande</button>`:'Commande non saisie']))}</div>`;}

let jumiaFuelResult=null,jumiaFuelRevision=0;
const jumiaFuelStoreSelection=new Map();
function jumiaLatestFuelDate(vehicle=''){return state.expenses.filter(e=>e.active!==false&&e.fuel&&(!vehicle||e.fuel.vehicle===vehicle)).map(e=>e.date).filter(Boolean).sort().at(-1)||chargeDate();}
function renderJumiaFuelAnalysis(){const vehicles=[...new Set(state.expenses.filter(e=>e.active!==false&&e.fuel?.vehicle).map(e=>e.fuel.vehicle))];return `<div class="panel"><h3>Commandes livrées : rentabilité après gasoil</h3><form id="jumia-fuel-analysis-form"><fieldset><legend>Boutiques (toutes sélectionnées par défaut)</legend>${state.jumiaStores.filter(s=>s.active!==false).map(s=>`<label><input type="checkbox" name="storeIds" value="${s.id}" ${jumiaFuelStoreSelection.get(String(s.id))!==false?'checked':''}> ${esc(s.name)}</label>`).join('')}</fieldset><fieldset><legend>Exports CSV par boutique (facultatifs)</legend>${state.jumiaStores.filter(s=>s.active!==false).map(s=>`<div data-fuel-upload="${s.id}" style="${jumiaFuelStoreSelection.get(String(s.id))===false?'display:none':''}"><label>${esc(s.name)}<input type="file" data-fuel-store="${s.id}" accept=".csv,text/csv" multiple></label></div>`).join('')}<p>Ajoutez les fichiers de chaque boutique dans son champ. Plusieurs fichiers possibles par boutique ; seuls ceux des boutiques cochées seront analysés. Maximum 2 Mo au total.</p></fieldset>${field('from','Commandes et pleins du','date',jumiaLatestFuelDate())}${field('to','Au','date',chargeDate())}<label>Voiture<select name="vehicle"><option value="">Tous les véhicules</option>${vehicles.map(v=>`<option>${esc(v)}</option>`).join('')}</select></label><label>Gasoil restant du dernier plein (%)<input name="fuelRemainingPercent" type="number" min="0" max="100" step="any" value="0" required></label><label>Usage personnel du gasoil consommé (%)<input name="personalUsePercent" type="number" min="0" max="100" step="any" value="0" required></label><button>Analyser</button><button type="button" id="jumia-fuel-cancel" class="secondary">Annuler</button><p id="jumia-fuel-error" role="alert"></p></form><p>Commandes au statut Livré / Delivered, filtrées uniquement par date d’expédition (Shipped Date), dans tous les fichiers et sans CSV. Le début effectif est la date du premier plein actif de la période et du véhicule choisis ; les expéditions antérieures sont exclues. Les commandes sans date d’expédition valide sont exclues. Avec CSV : lignes Delivered des fichiers et commandes Livré de la période des autres boutiques sélectionnées ; les boutiques avec fichiers utilisent uniquement leurs exports. Décochez une boutique pour l’exclure. Analyse = ventes livrées − prix d’achat − frais Jumia − ticket / carton / sel et autres frais − gasoil professionnel estimé. La part personnelle s’applique au gasoil consommé après déduction de la part restante (30 % personnel = 70 % professionnel). La proportion restante s’applique uniquement au dernier plein de la période et du véhicule choisis. Gasoil consommé = total des pleins − part restante du dernier plein. Transport fournisseur, transport hub et transport retour sont exclus. La contribution shipping facturée par Jumia reste un frais Jumia. L’analyse ne crée ni commande ni paiement.</p></div><div id="jumia-fuel-result">${jumiaFuelResult?jumiaFuelResultMarkup(jumiaFuelResult):''}</div>`;}
function jumiaFuelResultMarkup(r){return `<div class="panel"><h3>${esc(r.storeName)} · ${r.orderCount} commandes livrées · ${r.deliveryCount} livraisons (voyages)</h3><p>Période choisie du ${esc(r.from)} au ${esc(r.to)} · Expéditions prises en compte du ${esc(r.effectiveFrom)} (premier plein) au ${esc(r.to)}. ${r.excluded} lignes non Delivered exclues · ${r.excludedPeriod} lignes CSV / commandes hors période d’expédition exclues · ${r.excludedMissingShipping} lignes CSV / commandes sans date d’expédition valide exclues.</p>${r.missing?`<p role="alert">${r.missing} ligne(s) à rapprocher : le résultat global reste à vérifier. Les montants ci-dessous portent sur les lignes rapprochées.</p>`:''}<div class="cards">${[['CA rapproché',money(r.salesCents/100)],['Coût d’achat',money(r.purchaseCents/100)],['Frais Jumia',money(r.jumiaFeesCents/100)],['Emballage / autres frais',money(r.packagingCents/100)],['Marge avant gasoil',money(r.beforeFuelCents/100)],['Gasoil acheté',money(r.fuelCents/100)],['Dernier plein ('+r.lastFuelDate+')',money(r.lastFuelCents/100)],['Gasoil consommé total',money(r.fuelConsumedCents/100)],['Gasoil usage personnel ('+r.personalUsePercent+' %)',money(r.personalFuelCents/100)],['Gasoil professionnel déduit',money(r.businessFuelCents/100)],['Gasoil / livraison',money(r.fuelPerDeliveryCents/100)],['Gasoil + ticket + emballage / livraison',r.costPerDeliveryCents===null?'À vérifier':money(r.costPerDeliveryCents/100)],['Gasoil restant ('+r.fuelRemainingPercent+' % du dernier plein)',money(r.fuelRemainingCents/100)],['Litres achetés',r.fuelLitres.toFixed(3)+' L'],['Litres consommés estimés',r.fuelConsumedLitres.toFixed(3)+' L'],['Litres restants estimés',r.fuelRemainingLitres.toFixed(3)+' L'],['Résultat après gasoil',r.profitCents===null?'À vérifier':money(r.profitCents/100)]].map(([label,value])=>`<div class="card">${label}<strong>${value}</strong></div>`).join('')}</div><p><strong>${r.profitCents===null?'Rapprochez les commandes et leurs prix d’achat pour connaître le bénéfice ou la perte.':r.profitCents>0?'Bénéfice après gasoil':r.profitCents<0?'Perte après gasoil':'Résultat équilibré'}</strong></p><p>Une livraison = un voyage : les commandes expédiées le même jour dans la même heure (Shipped Date) sont regroupées, toutes boutiques sélectionnées confondues. ${r.undatedOrderCount?`${r.undatedOrderCount} commande(s) sans heure d’expédition : comptées séparément, nombre de voyages à vérifier. Fournissez un CSV avec Shipped Date pour les regrouper.`:''} Coût gasoil / livraison = gasoil professionnel après déduction des parts restante et personnelle ÷ ${r.deliveryCount} livraisons (voyages). Coût avec ticket et emballage = (gasoil professionnel + ticket + carton + sel) ÷ ce même nombre de voyages, sans frais de transport ni autres frais. Seule la part professionnelle estimée du gasoil consommé est déduite, une seule fois pour toutes les boutiques sélectionnées. Les pleins comparés sont tous les pleins actifs de la période et du véhicule choisis. Pour un export partiel, ticket et emballage sont répartis au prorata des quantités de la commande.</p>${table(['Boutique','Commande','Produit / SKU','Quantité livrée','Vente','Coût achat','Frais Jumia','État'],r.details.map(d=>[esc(d.storeName),esc(d.number),esc(d.name)+' / '+esc(d.sku),d.qty,money(d.salesCents/100),d.purchaseCents===null?'À vérifier':money(d.purchaseCents/100),d.jumiaFeesCents===null?'À vérifier':money(d.jumiaFeesCents/100),esc(d.error||'Rapproché')]))}<h3>Pleins gasoil pris en compte</h3>${table(['Date','Voiture','Station','Montant','Litres'],r.fuel.map(f=>[esc(f.date),esc(f.vehicle),esc(f.station),money(f.amountCents/100),f.litres.toFixed(3)+' L']))}</div>`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='jumia-fuel-analysis-form')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,button=form.querySelector('button'),revision=++jumiaFuelRevision;button.disabled=true;jumiaFuelResult=null;$('#jumia-fuel-result').innerHTML='';$('#jumia-fuel-error').textContent='';try{const data=Object.fromEntries(new FormData(form)),storeIds=new FormData(form).getAll('storeIds').map(Number),uploads=[...form.querySelectorAll('[data-fuel-store]')].filter(input=>storeIds.includes(Number(input.dataset.fuelStore))).flatMap(input=>[...input.files].map(file=>({file,storeId:Number(input.dataset.fuelStore)})));if(uploads.reduce((n,u)=>n+u.file.size,0)>2*1024*1024)throw Error('CSV : maximum 2 Mo au total');const files=await Promise.all(uploads.map(async u=>({storeId:u.storeId,csv:await u.file.text()}))); const result=await api('jumiaFuelAnalysis',{...data,storeIds,fuelRemainingPercent:Number(data.fuelRemainingPercent),personalUsePercent:Number(data.personalUsePercent),files});if(revision!==jumiaFuelRevision)return;jumiaFuelResult=result;$('#jumia-fuel-result').innerHTML=jumiaFuelResultMarkup(result);}catch(error){if(revision===jumiaFuelRevision)$('#jumia-fuel-error').textContent=error.message;}finally{if(revision===jumiaFuelRevision)button.disabled=false;}},true);
document.addEventListener('click',e=>{if(!e.target.closest('#jumia-fuel-cancel'))return;jumiaFuelRevision++;jumiaFuelResult=null;const form=$('#jumia-fuel-analysis-form');form.querySelectorAll('[data-fuel-store]').forEach(input=>{input.value='';});form.querySelector('button').disabled=false;$('#jumia-fuel-result').innerHTML='';$('#jumia-fuel-error').textContent='';});

document.addEventListener('change',e=>{if(e.target.form?.id!=='jumia-fuel-analysis-form'||e.target.name!=='vehicle')return;e.target.form.elements.from.value=jumiaLatestFuelDate(e.target.value);});

document.addEventListener('change',e=>{const input=e.target,form=input.form;if(form?.id!=='jumia-fuel-analysis-form'||input.name!=='storeIds')return;jumiaFuelStoreSelection.set(input.value,input.checked);for(const row of form.querySelectorAll('[data-fuel-upload]'))if(row.dataset.fuelUpload===input.value)row.style.display=input.checked?'':'none';jumiaFuelRevision++;jumiaFuelResult=null;form.querySelector('button').disabled=false;$('#jumia-fuel-result').innerHTML='';$('#jumia-fuel-error').textContent='';});

let jumiaCorrectionPreview=null,jumiaCorrectionRequest=null,jumiaCorrectionRevision=0;
function orderCorrectionMarkup(){const options=state.jumiaStores.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');return `<div class="panel"><h3>Corriger la boutique d’un import commandes</h3><p>Chargez le même CSV, choisissez la boutique où les commandes ont été importées par erreur et la boutique correcte. Les commandes sont déplacées avec leurs coûts, statuts et historique ; elles ne sont pas réimportées. Les listings sont copiés dans la destination et retirés de la source s’ils ne sont plus utilisés. Si les commandes ont déjà été déplacées par cette correction, rechargez le même CSV pour nettoyer les listings restants. Les doublons, quantités incompatibles et commandes liées à un relevé financier sont bloqués.</p><form id="jumia-correction-form"><label>Boutique source (erreur)<select name="sourceStoreId" required><option value="">Choisir</option>${options}</select></label><label>Boutique destination (correcte)<select name="targetStoreId" required><option value="">Choisir</option>${options}</select></label><label>CSV des commandes à corriger<input type="file" name="csvFile" accept=".csv,text/csv" required></label><button>Vérifier la correction</button><p id="jumia-correction-error" role="alert"></p></form><div id="jumia-correction-preview"></div></div>`;}
document.addEventListener('submit',async e=>{if(e.target.id!=='jumia-correction-form')return;e.preventDefault();e.stopImmediatePropagation();const form=e.target,button=form.querySelector('button'),revision=++jumiaCorrectionRevision;button.disabled=true;jumiaCorrectionPreview=null;jumiaCorrectionRequest=null;$('#jumia-correction-preview').innerHTML='';try{const file=form.elements.csvFile.files[0];if(!file||file.size>2*1024*1024)throw Error('CSV : maximum 2 Mo');const request={sourceStoreId:Number(form.elements.sourceStoreId.value),targetStoreId:Number(form.elements.targetStoreId.value),csv:await file.text()};const preview=await api('jumiaOrderImports',{...request,action:'previewMove'});if(revision!==jumiaCorrectionRevision)return;jumiaCorrectionRequest=request;jumiaCorrectionPreview=preview;$('#jumia-correction-error').textContent='';$('#jumia-correction-preview').innerHTML=`<h3>${esc(preview.sourceName)} → ${esc(preview.targetName)}</h3>${table(['Sélection','Commande','Vérification'],preview.orders.map(o=>[`<input type="checkbox" data-correct-order="${esc(o.number)}" ${o.errors.length?'disabled':'checked'}>`,esc(o.number),o.errors.map(esc).join('<br>')||(o.alreadyMoved?'Déjà déplacée : corriger les listings':'Commande et listings prêts à déplacer')]))}<p>Listings source concernés (si toutes les commandes valides sont sélectionnées) : ${preview.sourceListings.map(l=>esc(l.sku)+' — '+(l.kept?'conservé car encore utilisé':'retiré de la source')).join(', ')||'Aucun'}.</p>${field('correctionReason','Motif de correction','text','Import dans la mauvaise boutique')}<div class="confirmation-actions"><label><input type="checkbox" id="jumia-correction-confirm"> Je confirme le déplacement de ${esc(preview.sourceName)} vers ${esc(preview.targetName)}.</label><button type="button" id="jumia-correction-commit">Corriger les commandes et listings sélectionnés</button></div>`;}catch(error){$('#jumia-correction-error').textContent=error.message;}finally{button.disabled=false;}},true);
document.addEventListener('click',async e=>{const button=e.target.closest('#jumia-correction-commit');if(!button)return;button.disabled=true;try{if(!jumiaCorrectionPreview||!$('#jumia-correction-confirm')?.checked)throw Error('Confirmez la boutique source et destination');const selectedOrders=[...document.querySelectorAll('[data-correct-order]:checked')].map(input=>input.dataset.correctOrder),reason=document.querySelector('[name="correctionReason"]').value;const result=await api('jumiaOrderImports',{...jumiaCorrectionRequest,action:'commitMove',selectedOrders,reason,expectedPreview:JSON.stringify(jumiaCorrectionPreview)});jumiaCorrectionPreview=null;jumiaCorrectionRequest=null;await load();$('#notice').textContent=result.moved+' commande(s) déplacée(s), '+result.listingsRepaired+' commande(s) déjà déplacée(s) vérifiée(s), '+result.listingsRemoved+' listing(s) retiré(s) de la boutique source.';}catch(error){$('#jumia-correction-error').textContent=error.message;button.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.form?.id==='jumia-orders-import-form'){jumiaOrderImportRevision++;jumiaOrderImportPreview=null;jumiaOrderImportRequest=null;$('#jumia-orders-import-preview').innerHTML='';}if(e.target.form?.id==='jumia-correction-form'){jumiaCorrectionRevision++;jumiaCorrectionPreview=null;jumiaCorrectionRequest=null;$('#jumia-correction-preview').innerHTML='';}});

document.addEventListener('click',e=>{const button=e.target.closest('#jumia-inline-import-toggle');if(!button)return;const panel=$('#jumia-inline-import');panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){const form=panel.querySelector('#jumia-orders-import-form');if(jumiaFilters.store&&[...form.elements.storeId.options].some(o=>o.value===jumiaFilters.store))form.elements.storeId.value=jumiaFilters.store;form.elements.storeId.focus();panel.scrollIntoView({behavior:'smooth',block:'start'});}});

document.addEventListener('change',e=>{if(e.target.id==='jumia-listing-availability'){jumiaListingAvailability=e.target.value;render();}});

function cancellationResponsibilityMarkup(order){if(!order.lines.some(l=>l.status==='Annulé'))return '';const counted=order.lines.some(l=>cancellationOnClient(order,l));return `<section class="panel"><h3>Suivi client — annulation</h3><p>${counted?'Annulation comptée sur le client — à surveiller.':'Annulation côté vendeur : non comptée sur le client.'}</p><p>Out of stock est attribué au vendeur par défaut. Ce choix concerne uniquement le suivi client : la commande reste annulée et son motif Jumia est conservé.</p>${canManageJumia()?`<label>Attribution<select id="cancellation-client-owner"><option value="auto" ${order.cancellationOnClient==null?'selected':''}>Automatique selon le motif</option><option value="seller" ${order.cancellationOnClient===false?'selected':''}>Vendeur — ne pas compter sur le client</option><option value="client" ${order.cancellationOnClient===true?'selected':''}>Client — compter sur le client / à surveiller</option></select></label><button type="button" data-cancellation-owner="${order.id}">Enregistrer l’attribution</button><p data-cancellation-error role="alert"></p>`:''}</section>`;}
document.addEventListener('click',async event=>{const button=event.target.closest('[data-cancellation-owner]');if(!button||button.disabled)return;const order=state.jumiaOrders.find(o=>o.id===Number(button.dataset.cancellationOwner));if(!order)return;const choice=document.getElementById('cancellation-client-owner').value,assignment=choice==='auto'?null:choice==='client';button.disabled=true;try{await api('jumiaOrders',{id:order.id,expectedRecord:JSON.stringify(order),action:'cancellationResponsibility',cancellationOnClient:assignment,reason:'Attribution annulation : '+(assignment===null?'automatique':assignment?'client':'vendeur')});$('#jumia-dialog').close();await load();}catch(error){document.querySelector('[data-cancellation-error]').textContent=error.message;}finally{button.disabled=false;}});

document.addEventListener('click',async e=>{const button=e.target.closest('[data-catalog-save-row]');if(!button||catalogRowBusy||!catalogRequest)return;const sku=button.dataset.catalogSaveRow,row=button.closest('tr'),message=row.querySelector('[data-catalog-row-message]'),revision=catalogRevision,account=state.currentUser.id,request={...catalogRequest,productMatches:{...catalogRequest.productMatches}};const controls=[...button.closest('.panel').querySelectorAll('button,input,select')].map(control=>({control,disabled:control.disabled}));catalogRowBusy=true;controls.forEach(({control})=>control.disabled=true);button.textContent='Enregistrement…';message.textContent='';let saved=false;try{const preview=await api('jumiaCatalogImports',{...request,action:'preview'});if(revision!==catalogRevision||state.currentUser.id!==account)return;const result=await api('jumiaCatalogImports',{...request,action:'commit',selectedSkus:[sku],expectedPreview:JSON.stringify(preview)});saved=true;if(revision!==catalogRevision||state.currentUser.id!==account)return;if(result.store){const index=state.jumiaStores.findIndex(s=>s.id===result.store.id);if(index>=0)state.jumiaStores[index]=result.store;}catalogPreview=null;button.textContent='Enregistré';message.textContent='Listing enregistré.';}catch(error){if(revision===catalogRevision)message.textContent=error.message;}finally{controls.forEach(({control,disabled})=>control.disabled=disabled);if(saved){row.querySelectorAll('input,select,button').forEach(control=>control.disabled=true);}else button.textContent='Enregistrer';const bulk=document.getElementById('catalog-commit');if(bulk)bulk.disabled=true;catalogRowBusy=false;}});
